insert into public.metric_definitions (code, name, unit, category, protocol, frequency, comparability_notes, higher_is_better, is_impact, inputs, version) values ('waste_per_student', 'Waste generated', 'g per student per school day', 'waste', 'Weigh every waste stream at the collection point for the whole period. Divide by enrolled students and school days in the period.', 'Weekly', 'Uses enrolled students, not attendance. Exclude construction waste.', false, true, '[{"key":"total_kg","label":"Total waste weighed","unit":"kg"},{"key":"school_days","label":"School days covered","unit":"days"}]'::jsonb, 1)
insert into public.metric_definitions (code, name, unit, category, protocol, frequency, comparability_notes, higher_is_better, is_impact, inputs, version) values ('diversion_rate', 'Diversion rate', '% of waste recycled or composted', 'waste', 'Weigh recycled and composted streams separately from residual waste over the same period.', 'Weekly', 'Count only material that actually leaves for recycling or enters the compost, not what was put in the bins.', true, true, '[{"key":"diverted_kg","label":"Recycled + composted","unit":"kg"},{"key":"total_kg","label":"Total waste","unit":"kg"}]'::jsonb, 1)
insert into public.metric_definitions (code, name, unit, category, protocol, frequency, comparability_notes, higher_is_better, is_impact, inputs, version) values ('compost_contamination', 'Compost contamination', '% non-compostable by weight', 'waste', 'Take a 5 kg sample from the compost input stream, sort out non-compostable items and weigh them.', 'Fortnightly', 'Poorly monitored systems often reach 30–50%. Sample on a normal school day.', false, true, '[{"key":"contaminant_kg","label":"Non-compostable found","unit":"kg"},{"key":"sample_kg","label":"Sample weight","unit":"kg"}]'::jsonb, 1)
insert into public.metric_definitions (code, name, unit, category, protocol, frequency, comparability_notes, higher_is_better, is_impact, inputs, version) values ('segregation_accuracy', 'Segregation accuracy', '% items correctly sorted', 'waste', 'Spot-audit 3 bin stations. Count items in each bin and how many are in the right bin.', 'Weekly', 'Audit unannounced, at the same time of day each week.', true, true, '[{"key":"correct","label":"Items in the right bin","unit":"items"},{"key":"checked","label":"Items checked","unit":"items"}]'::jsonb, 1)
insert into public.metric_definitions (code, name, unit, category, protocol, frequency, comparability_notes, higher_is_better, is_impact, inputs, version) values ('single_use_plastic', 'Single-use plastic items', 'items per week', 'waste', 'Count single-use plastic items (bottles, cutlery, wrappers, cups) in a full week of collected waste from the canteen and events.', 'Weekly', 'Report per week; normalise per 100 students when comparing schools.', false, true, '[{"key":"items","label":"Items counted","unit":"items"}]'::jsonb, 1)
insert into public.metric_definitions (code, name, unit, category, protocol, frequency, comparability_notes, higher_is_better, is_impact, inputs, version) values ('canteen_waste_per_meal', 'Canteen food waste', 'g per meal served', 'food', 'Weigh plate and kitchen food waste each day. Divide by meals served.', 'Weekly', 'Include both plate waste and kitchen prep waste.', false, true, '[{"key":"food_kg","label":"Food waste weighed","unit":"kg"},{"key":"meals","label":"Meals served","unit":"meals"}]'::jsonb, 1)
insert into public.metric_definitions (code, name, unit, category, protocol, frequency, comparability_notes, higher_is_better, is_impact, inputs, version) values ('energy_per_student', 'Electricity use', 'kWh per student per month', 'energy', 'Read the main meter on the first school day of each month.', 'Monthly', 'Note air-conditioning months separately.', false, true, '[{"key":"kwh","label":"Meter reading difference","unit":"kWh"}]'::jsonb, 1)
insert into public.metric_definitions (code, name, unit, category, protocol, frequency, comparability_notes, higher_is_better, is_impact, inputs, version) values ('renewable_share', 'Renewable share', '% of electricity from on-site renewables', 'energy', 'Read solar generation and main meter on the same day each month.', 'Monthly', 'On-site generation only.', true, true, '[{"key":"renewable_kwh","label":"Solar generated","unit":"kWh"},{"key":"total_kwh","label":"Total used","unit":"kWh"}]'::jsonb, 1)
insert into public.metric_definitions (code, name, unit, category, protocol, frequency, comparability_notes, higher_is_better, is_impact, inputs, version) values ('water_per_student', 'Water use', 'litres per student per school day', 'water', 'Read the water meter weekly; divide by enrolled students and school days.', 'Weekly', 'Exclude tanker deliveries for construction.', false, true, '[{"key":"litres","label":"Litres used","unit":"L"},{"key":"school_days","label":"School days covered","unit":"days"}]'::jsonb, 1)
insert into public.metric_definitions (code, name, unit, category, protocol, frequency, comparability_notes, higher_is_better, is_impact, inputs, version) values ('participation', 'Participation', '% of classes engaged', 'participation', 'Count classes that took part in the activity this period.', 'Monthly', 'Participation, not impact. Never reported as an outcome.', true, false, '[{"key":"classes_engaged","label":"Classes engaged","unit":"classes"},{"key":"classes_total","label":"Total classes","unit":"classes"}]'::jsonb, 1)
insert into public.metric_definitions (code, name, unit, category, protocol, frequency, comparability_notes, higher_is_better, is_impact, inputs, version) values ('cost', 'Cost', 'USD (fixed annual rate)', 'cost', 'Record money spent or saved in local currency; the platform converts at the fixed annual rate.', 'Per transaction', 'Rates are fixed once a year so comparisons stay stable.', false, false, '[{"key":"local_amount","label":"Amount in local currency","unit":"local"}]'::jsonb, 1)
insert into public.circles (name, theme, description) values ('Waste', 'waste', 'Audits, segregation, composting and plastics.') on conflict (theme) do nothing;
insert into public.circles (name, theme, description) values ('Energy', 'energy', 'Meters, solar and student-facing dashboards.') on conflict (theme) do nothing;
insert into public.circles (name, theme, description) values ('Water', 'water', 'Meters, leaks and harvesting.') on conflict (theme) do nothing;
insert into public.circles (name, theme, description) values ('Food', 'food', 'Canteens, plate waste and gardens.') on conflict (theme) do nothing;
insert into public.circles (name, theme, description) values ('Biodiversity', 'biodiversity', 'Campus habitats and native planting.') on conflict (theme) do nothing;
insert into public.circles (name, theme, description) values ('Policy & governance', 'policy', 'Approval chains, budgets and school policy.') on conflict (theme) do nothing;
insert into public.policy_clauses (section, title, body, adoption_count) select 'summary', 'Summary', 'This policy embeds sustainability in the school’s operations, teaching and community life. It sets out how projects are proposed, approved, documented, measured and handed over so that they continue across student cohorts.', 0 where not exists (select 1 from public.policy_clauses where title = 'Summary');
insert into public.policy_clauses (section, title, body, adoption_count) select 'purpose', 'Clarity and consistency', 'All sustainability projects follow one route for proposal, approval, implementation, documentation and evaluation.', 0 where not exists (select 1 from public.policy_clauses where title = 'Clarity and consistency');
insert into public.policy_clauses (section, title, body, adoption_count) select 'purpose', 'Continuity', 'Knowledge transfer and project handover are planned so that initiatives do not dissolve when students graduate or staff move on.', 0 where not exists (select 1 from public.policy_clauses where title = 'Continuity');
insert into public.policy_clauses (section, title, body, adoption_count) select 'purpose', 'Practical integration', 'Sustainability work is built into existing operations, curriculum planning and community engagement rather than run as isolated events.', 0 where not exists (select 1 from public.policy_clauses where title = 'Practical integration');
insert into public.policy_clauses (section, title, body, adoption_count) select 'documentation', 'Documentation and knowledge transfer', 'Every project keeps its proposal, progress reports, data, photographic evidence and reflections in one shared digital repository, using standard templates.', 0 where not exists (select 1 from public.policy_clauses where title = 'Documentation and knowledge transfer');
insert into public.policy_clauses (section, title, body, adoption_count) select 'student_leadership', 'Student leadership with institutional support', 'Students initiate, lead and manage projects through a Student Sustainability Board. The school allocates resources, assigns a staff mentor, and offers training in project management and communication.', 0 where not exists (select 1 from public.policy_clauses where title = 'Student leadership with institutional support');
insert into public.policy_clauses (section, title, body, adoption_count) select 'measurement', 'Measurable progress and adaptive management', 'Each project names simple, comparable indicators, such as waste per student or diversion rate, and reviews them regularly to adjust its design.', 0 where not exists (select 1 from public.policy_clauses where title = 'Measurable progress and adaptive management');
insert into public.policy_clauses (section, title, body, adoption_count) select 'reflection', 'Reflection and transparency', 'Successes and failures are both recorded and shared. The school publishes what did not work alongside what did.', 0 where not exists (select 1 from public.policy_clauses where title = 'Reflection and transparency');
insert into public.policy_clauses (section, title, body, adoption_count) select 'roles', 'Roles and terms', 'The Student Sustainability Board has six seats with staggered terms so that half the board changes each half-year. The Faculty Liaison is the permanent owner of project records.', 0 where not exists (select 1 from public.policy_clauses where title = 'Roles and terms');
insert into public.policy_clauses (section, title, body, adoption_count) select 'continuity', 'Handover', 'Outgoing leads prepare a handover packet eight weeks before their term ends and sign it with their successor and the Faculty Liaison.', 0 where not exists (select 1 from public.policy_clauses where title = 'Handover');
insert into public.policy_clauses (section, title, body, adoption_count) select 'partnerships', 'Community partnerships', 'The Sustainability Coordinator develops partnerships with local environmental organisations, sustainable businesses, local government and other schools.', 0 where not exists (select 1 from public.policy_clauses where title = 'Community partnerships');
insert into public.policy_clauses (section, title, body, adoption_count) select 'workshops', 'Workshops and events', 'The school runs practical workshops for parents and community members on composting, waste reduction, gardening and energy efficiency.', 0 where not exists (select 1 from public.policy_clauses where title = 'Workshops and events');
insert into public.policy_clauses (section, title, body, adoption_count) select 'climate_cafes', 'Climate Cafés', 'Regular informal sessions give parents and caregivers a space to discuss sustainability and feed home perspectives back into school practice.', 0 where not exists (select 1 from public.policy_clauses where title = 'Climate Cafés');
insert into public.policy_clauses (section, title, body, adoption_count) select 'review', 'Review', 'The policy is reviewed every year by the Student Sustainability Board and the Faculty Liaison, and amendments are recorded.', 0 where not exists (select 1 from public.policy_clauses where title = 'Review');
insert into public.policy_clauses (section, title, body, adoption_count) select 'waste', 'Waste reduction, segregation and composting', 'The school sorts waste at source into at least recyclables, organics and residual, with labelled bins in classrooms, the canteen and common areas. Food and garden waste is composted on site or by an approved partner. A baseline waste audit is repeated each year and the school sets a diversion target from it.', 0 where not exists (select 1 from public.policy_clauses where title = 'Waste reduction, segregation and composting');
insert into public.policy_clauses (section, title, body, adoption_count) select 'plastics', 'Single-use plastics', 'The school phases out single-use plastic items it controls, such as bottles, cutlery, straws and packaging in the canteen and at events. Refill points are provided and progress is counted each term.', 0 where not exists (select 1 from public.policy_clauses where title = 'Single-use plastics');
insert into public.policy_clauses (section, title, body, adoption_count) select 'energy', 'Energy use and renewables', 'The school meters its electricity, publishes monthly use per student, and sets a reduction target. Lights and equipment are switched off when rooms are empty, and renewable sources are considered for every major upgrade.', 0 where not exists (select 1 from public.policy_clauses where title = 'Energy use and renewables');
insert into public.policy_clauses (section, title, body, adoption_count) select 'water', 'Water conservation', 'The school reads its water meters weekly, reports leaks within one working day, and fits low-flow fittings when replacing taps and toilets. Rainwater harvesting and reuse are assessed for each new building or renovation.', 0 where not exists (select 1 from public.policy_clauses where title = 'Water conservation');
insert into public.policy_clauses (section, title, body, adoption_count) select 'procurement', 'Sustainable procurement', 'When buying stationery, furniture, food and cleaning products, the school prefers durable, repairable, recycled or locally sourced options and asks suppliers to reduce packaging. Purchases above an agreed value are checked against this clause before approval.', 0 where not exists (select 1 from public.policy_clauses where title = 'Sustainable procurement');
insert into public.policy_clauses (section, title, body, adoption_count) select 'curriculum', 'Sustainability in teaching and staff training', 'Each year group includes at least one sustainability topic or project linked to the subjects it studies. New teachers receive an onboarding booklet on the school’s sustainability policies, and all staff are offered training each year.', 0 where not exists (select 1 from public.policy_clauses where title = 'Sustainability in teaching and staff training');
insert into public.policy_clauses (section, title, body, adoption_count) select 'safeguarding', 'Safety and wellbeing in sustainability work', 'Sustainability activities are risk-assessed and supervised by an adult. Student photos and personal details are shared only with consent from the student and, for minors, a parent or guardian.', 0 where not exists (select 1 from public.policy_clauses where title = 'Safety and wellbeing in sustainability work');
insert into public.cohorts (name, starts_on) select 'Founding Cohort', current_date where not exists (select 1 from public.cohorts where name = 'Founding Cohort');
insert into public.organisations (name, org_type, country, city, status) select 'Ekoa Stewards', 'ekoa', 'India', 'Faridabad', 'active' where not exists (select 1 from public.organisations where org_type = 'ekoa');
insert into public.organisations (name, org_type, country, city, status, public_visible, audit_school) select 'Shiv Nadar School, Faridabad', 'school', 'India', 'Faridabad', 'active', true, true where not exists (select 1 from public.organisations where name = 'Shiv Nadar School, Faridabad');
insert into public.organisations (name, org_type, country, city, status, public_visible, audit_school) select 'Green School, Bali', 'school', 'Indonesia', 'Badung, Bali', 'active', true, true where not exists (select 1 from public.organisations where name = 'Green School, Bali');
